	@Test
	void reopensRetainedTripleTermAfterGcRetiresForwardMapping() throws Exception {
		var values = SimpleValueFactory.getInstance();
		var subject = values.createIRI("urn:gc:subject");
		var predicate = values.createIRI("urn:gc:predicate");
		var quoted = values.createTripleTerm(values.createIRI("urn:gc:inner"), predicate,
				values.createLiteral("unreferenced component"));
		// Bounded reclamation needs a leading object index to establish term liveness.
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setInlineLiterals(false)
				// This fixture deliberately retains reverse-only records until the next startup batch.
				.setAsyncValueCleanup(false)
				.setValueEvictionInterval(60_000)
				.setLegacyReferenceCountRepairEnabled(true);
		SailRepository initial = new SailRepository(new LmdbStore(directory.toFile(), config));
		initial.init();
		try (var connection = initial.getConnection()) {
			connection.add(subject, predicate, quoted);
		} finally {
			initial.shutDown();
		}
		LmdbStore.reconstructReferenceCountsOffline(directory.toFile(), config);
		SailRepository removing = new SailRepository(new LmdbStore(directory.toFile(), config));
		try (var connection = removing.getConnection()) {
			connection.remove(subject, predicate, quoted);
			assertThat(connection.size()).isZero();
		} finally {
			removing.shutDown();
		}

		List<byte[]> ownerKeys = readNativeKeys(directory.resolve("values"),
				TripleIndex.nativeDatabaseName("term-cspo", true));
		assertThat(ownerKeys).hasSize(1);
		long[] quad = decodeCspoTermKey(ownerKeys.get(0));
		long owner = quad[TripleIndex.CONTEXT_IDX];
		assertThat(hasUnusedMarker(owner)).isTrue();
		assertThat(ValueIds.getIdType(owner)).isEqualTo(ValueIds.T_TRIPLE);
		String spocDatabase = TripleIndex.nativeDatabaseName("term-spoc", true);
		assertThat(LmdbCompatibilityFixtures.nativeGet(directory, spocDatabase, encodeIndexKey("spoc", quad)))
				.as("GC removes the retired term's live forward mapping")
				.isNull();

		SailRepository reopened = new SailRepository(new LmdbStore(directory.toFile(), config));
		reopened.init();
		try (var connection = reopened.getConnection()) {
			assertThat(connection.size()).isZero();
		} finally {
			reopened.shutDown();
		}
	}

