	@Test
	void rejectsRetainedTripleTermWithMissingChildRowDespiteRetirementMarker() throws Exception {
		var values = SimpleValueFactory.getInstance();
		var predicate = values.createIRI("urn:retained:predicate");
		var inner = values.createTripleTerm(values.createIRI("urn:retained:inner"), predicate,
				values.createLiteral("inner"));
		var outer = values.createTripleTerm(values.createIRI("urn:retained:outer"), predicate, inner);
		SailRepository initial = repository();
		initial.init();
		try (var connection = initial.getConnection()) {
			connection.add(values.createIRI("urn:retained:statement"), predicate, outer);
		} finally {
			initial.shutDown();
		}

		Properties descriptors = properties(directory, "store.properties");
		List<byte[]> ownerKeys = readNativeKeys(directory.resolve("values"),
				TripleIndex.nativeDatabaseName("term-cspo", true));
		assertThat(ownerKeys).hasSize(2);
		long[][] quads = new long[ownerKeys.size()][];
		for (int index = 0; index < ownerKeys.size(); index++) {
			quads[index] = decodeCspoTermKey(ownerKeys.get(index));
		}
		long[] parentQuad = Arrays.stream(quads)
				.filter(quad -> ValueIds.getIdType(quad[TripleIndex.OBJ_IDX]) == ValueIds.T_TRIPLE)
				.findFirst()
				.orElseThrow();
		long childId = parentQuad[TripleIndex.OBJ_IDX];
		long[] childQuad = Arrays.stream(quads)
				.filter(quad -> quad[TripleIndex.CONTEXT_IDX] == childId)
				.findFirst()
				.orElseThrow();
		for (long[] quad : quads) {
			long owner = quad[TripleIndex.CONTEXT_IDX];
			for (String spec : TripleIndex.parseIndexSpecList(descriptors.getProperty("triple-term-indexes"))) {
				if (!spec.equals("cspo")) {
					LmdbCompatibilityFixtures.nativePut(directory,
							TripleIndex.nativeDatabaseName("term-" + spec, true), encodeIndexKey(spec, quad), null);
				}
			}
			addUnusedMarker(owner, 10);
			addUnusedMarker(owner, 11);
		}
		clearPersistentStatements();
		LmdbCompatibilityFixtures.nativePut(directory, TripleIndex.nativeDatabaseName("term-cspo", true),
				encodeIndexKey("cspo", childQuad), null);

		assertVerificationRejectedWithoutMutation();
	}

